package com.jlas.learning.service.impl.text;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;

import java.io.IOException;
import java.io.InputStream;
import java.io.UncheckedIOException;
import java.util.HashMap;
import java.util.Map;

/**
 * Owner 2026-10-24 (D3-09): the word type a vocabulary card shows, after Claude's review (owner-approved, so no "tự gán"
 * label any more). Learning's own copy ({@code learning/word-type-reviewed.json}, generated by
 * {@code tools/learning-data-extract/build_word_type_reviewed.mjs}); the shared {@code vocabulary_entry.word_type} is never
 * written.
 * <ul>
 *   <li>A dictionary value is kept, except raw source codes ("v", "n", "a-na"…), which get their Vietnamese label; a bare
 *       verb code takes the verb group {@link GeneratedWordType} finds.</li>
 *   <li>With no dictionary value, a reviewed expression wins over {@link GeneratedWordType}, which splits some kana-only
 *       words ("れいぞうこ") or reads them as the wrong class.</li>
 * </ul>
 */
public final class ReviewedWordType {
    static final String RESOURCE = "learning/word-type-reviewed.json";
    private static final String VERB = "Động từ";
    private static volatile Tables tables;

    private ReviewedWordType() { }

    /** Label for a card, or null when there is nothing to show. */
    public static String labelFor(String expression, String sourceWordType) {
        Tables t = tables();
        if (sourceWordType != null && !sourceWordType.isBlank()) {
            String source = sourceWordType.strip();
            String mapped = t.sourceCodes.get(source);
            if (mapped == null) return source;
            if (VERB.equals(mapped)) {
                String derived = GeneratedWordType.labelFor(expression);
                if (derived != null && derived.startsWith(VERB)) return derived;
            }
            return mapped;
        }
        if (expression == null || expression.isBlank()) return null;
        String reviewed = t.expressions.get(expression.strip());
        return reviewed != null ? reviewed : GeneratedWordType.labelFor(expression);
    }

    private static Tables tables() {
        Tables loaded = tables;
        if (loaded != null) return loaded;
        synchronized (ReviewedWordType.class) {
            if (tables == null) tables = load();
            return tables;
        }
    }

    private static Tables load() {
        try (InputStream in = ReviewedWordType.class.getClassLoader().getResourceAsStream(RESOURCE)) {
            if (in == null) throw new IllegalStateException("Missing " + RESOURCE);
            JsonNode root = new ObjectMapper().readTree(in);
            return new Tables(read(root.path("expressions")), read(root.path("sourceCodes")));
        } catch (IOException exception) {
            throw new UncheckedIOException(exception);
        }
    }

    private static Map<String, String> read(JsonNode node) {
        Map<String, String> values = new HashMap<>();
        node.fields().forEachRemaining(entry -> values.put(entry.getKey(), entry.getValue().asText()));
        return Map.copyOf(values);
    }

    private record Tables(Map<String, String> expressions, Map<String, String> sourceCodes) { }
}
